import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsedPercent: number;
  status: ProjectStatus;
}

const statusLabels: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'Приостановлен',
  over: 'Квота превышена',
};

const statusTones: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  paused: 'warning',
  over: 'danger',
};

const projects: Project[] = [
  { id: 'p1', name: 'Аналитика продаж', quotaUsedPercent: 42, status: 'active' },
  { id: 'p2', name: 'Внутренний портал', quotaUsedPercent: 88, status: 'active' },
  { id: 'p3', name: 'Миграция базы данных', quotaUsedPercent: 15, status: 'paused' },
  { id: 'p4', name: 'Мобильное приложение', quotaUsedPercent: 100, status: 'over' },
  { id: 'p5', name: 'Служба поддержки', quotaUsedPercent: 63, status: 'active' },
  { id: 'p6', name: 'Отчётность для клиентов', quotaUsedPercent: 5, status: 'paused' },
  { id: 'p7', name: 'Интеграция с CRM', quotaUsedPercent: 97, status: 'over' },
  { id: 'p8', name: 'Резервное копирование', quotaUsedPercent: 30, status: 'active' },
  { id: 'p9', name: 'Обучающая платформа', quotaUsedPercent: 71, status: 'active' },
  { id: 'p10', name: 'Партнёрская программа', quotaUsedPercent: 20, status: 'paused' },
  { id: 'p11', name: 'Логистика поставок', quotaUsedPercent: 105, status: 'over' },
  { id: 'p12', name: 'Финансовая сверка', quotaUsedPercent: 55, status: 'active' },
];

const allStatuses: ProjectStatus[] = ['active', 'paused', 'over'];
const pageSize = 5;

export default function ProjectQuotaPanel() {
  const [activeFilters, setActiveFilters] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const removeFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) => prev.filter((s) => s !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setActiveFilters([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeFilters.length === 0) return projects;
    return projects.filter((project) => activeFilters.includes(project.status));
  }, [activeFilters]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / pageSize));
  const visibleProjects = filteredProjects.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm, 14px)' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {allStatuses.map((status) => {
          const isActive = activeFilters.includes(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onRemove={() => removeFilter(status)}
              onClick={() => toggleFilter(status)}
            >
              {statusLabels[status]}
            </JxChip>
          );
        })}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Проекты не найдены"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                className="jx-row"
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '16px',
                  padding: '12px 16px',
                  borderRadius: 'var(--jx-r)',
                  border: '1px solid var(--jx-border)',
                  background: 'var(--jx-surface)',
                }}
              >
                <span style={{ color: 'var(--jx-text)', fontWeight: 500, flex: 1, minWidth: 0 }}>
                  {project.name}
                </span>
                <JxProgressCircle value={Math.min(project.quotaUsedPercent, 100)} showValue />
                <JxBadge tone={statusTones[project.status]} dot>
                  {statusLabels[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

